-- Master Matrix V1.0 seed. Architecture/model only; not empirical validation.
BEGIN;
CREATE TABLE IF NOT EXISTS mm_trait_nodes(node_id TEXT PRIMARY KEY,parent_node_id TEXT,domain TEXT,node_kind TEXT,name_en TEXT,name_ru TEXT,state_trait TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_trait_edges(edge_id BIGSERIAL PRIMARY KEY,from_node_id TEXT,to_node_id TEXT,edge_type TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_metrics_catalog(metric_id TEXT PRIMARY KEY,node_id TEXT,metric_name TEXT,unit TEXT,range_min DOUBLE PRECISION,range_max DOUBLE PRECISION,data_source TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_assessment_questions(question_id TEXT PRIMARY KEY,node_id TEXT,text_ru TEXT,text_en TEXT,scale TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_behavioral_tests(test_id TEXT PRIMARY KEY,node_id TEXT,name TEXT,protocol TEXT,primary_metric TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_load_levels(level_id TEXT PRIMARY KEY,name TEXT,social_pressure TEXT,cognitive_load TEXT,action_window TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_adaptation_rules(rule_id TEXT PRIMARY KEY,condition_text TEXT,action TEXT,value_text TEXT,reason TEXT,provenance TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mm_sprint_templates(sprint_id TEXT PRIMARY KEY,target_node_id TEXT,title TEXT,duration_days INT,supporting_habit TEXT,daily_action TEXT,level_progression JSONB,adaptation_rule_refs JSONB,evidence_status TEXT);
CREATE TABLE IF NOT EXISTS mm_roles(role_id TEXT PRIMARY KEY,name TEXT,dimensions JSONB);
CREATE TABLE IF NOT EXISTS mm_compatibility_rules(rule_id TEXT PRIMARY KEY,vector TEXT,inputs JSONB,outputs JSONB,status TEXT);
CREATE TABLE IF NOT EXISTS mm_claims(claim_id TEXT PRIMARY KEY,claim_text TEXT,status TEXT,provenance TEXT);
CREATE TABLE IF NOT EXISTS mm_validation_protocols(protocol_id TEXT PRIMARY KEY,name TEXT,status TEXT);
COMMIT;