INSERT INTO mm_assessment_questions VALUES('Q.P3.2.01','P3.2','Когда возникает сильный триггер, удается ли вам заметить стимул до действия?','When a strong trigger occurs, can you notice the stimulus before acting?','1-5','MDL') ON CONFLICT DO NOTHING;
INSERT INTO mm_assessment_questions VALUES('Q.P3.1.01','P3.1','Как часто вы действуете импульсивно, а затем жалеете о реакции?','How often do you act impulsively and later regret the reaction?','1-5','MDL') ON CONFLICT DO NOTHING;
INSERT INTO mm_assessment_questions VALUES('Q.P3.3.01','P3.3','Можете ли вы сформулировать альтернативное объяснение неприятной ситуации?','Can you formulate an alternative interpretation of an unpleasant situation?','1-5','EVD') ON CONFLICT DO NOTHING;
INSERT INTO mm_assessment_questions VALUES('Q.P5.1.01','P5.1','Какой процент запланированных коротких действий вы обычно доводите до конца?','What percentage of planned short actions do you usually complete?','0-100','RPT') ON CONFLICT DO NOTHING;
INSERT INTO mm_assessment_questions VALUES('Q.P5.3.01','P5.3','Насколько легко вам спокойно отказать в просьбе, которую вы не хотите выполнять?','How easy is it for you to calmly refuse a request you do not want to fulfill?','1-5','MDL') ON CONFLICT DO NOTHING;
